from lib import *
S = SS('v53')
steps = [
    step("KV 的版本号与 CAS。?cas=0 在 key 不存在时写入成功;key 已存在再 cas=0,返回 false;cas 给了一个不是当前 ModifyIndex 的数,返回 false;cas 等于当前 ModifyIndex 24,成功,之后 ModifyIndex 变成 27(它是全局递增的 Raft 索引,不是这个 key 自己的计数),CreateIndex 仍是 24。8 个线程各给同一个计数器加 50 次(应得 400):GET 后直接 PUT,最终值只有 66(应得 400),大部分更新被覆盖了,用时 0.71 s;GET 后 PUT ?cas=ModifyIndex,失败就重读重试,最终值 400,一共读-写了 2359 次,用时 4.88 s。", t=tl(S(1)), mark=lidx(S(1), 'GET 后 PUT(没有保护)', 'cas=0(key 已存在)'), done=lidx(S(1), 'GET 后 PUT ?cas', 'cas=24'), b=bars([['没有保护:最终值', 66, '66(应得 400)'], ['CAS:最终值', 400, '400'], ['CAS:读-写次数', 2359, '2359'], ['没有保护:读-写次数', 400, '400']], 2400, mark=[0], done=[1], cur=[2, 3]), kv=KV([['cas=0', '只在 key 不存在时成功'], ['cas=ModifyIndex', '只在没被改过时成功'], ['无保护计数器', '最终 66 / 400'], ['CAS 计数器', '最终 400,读-写 2359 次']], ['无保护计数器'])),
    step("阻塞查询。GET /v1/kv/w?index=N&wait=2s,没有变化时 5 次实际挂起 2.03、2.09、2.06、2.01、2.09 s,返回的索引与请求时相同。写入发生在 1 s 之后(经另一个 agent 写),3 次分别 1.01、1.02、1.02 s 返回,索引变大。watcher 一轮接一轮地查:顺序写 20 次(每 100 ms)看到 20 次变化,顺序写 200 次(每 2 ms)看到 200 次变化;8 个线程并发写共 400 次,watcher 只看到 203 次变化,最后看到的值等于 key 里的最终值;一个事务里对同一个 key 连续 set 10 次,watcher 只看到 1 次变化,值是 txn-9。", t=tl(S(2)), mark=lidx(S(2), '8 个线程并发写', '一个事务'), done=lidx(S(2), '无变化', '写入发生在', '顺序写'), b=bars([['并发写 400 次:watcher 看到', 203, '203'], ['顺序写 200 次:watcher 看到', 200, '200'], ['事务 set 10 次:watcher 看到', 1, '1']], 210, mark=[0, 2], done=[1]), kv=KV([['无变化', 'wait=2s 挂起约 2.0~2.1 s'], ['有写入', '约 1.01 s(写入发生时刻)返回'], ['并发写 400 次', 'watcher 看到 203 次'], ['一个事务写 10 次', 'watcher 看到 1 次']], ['并发写 400 次'])),
    step("session 锁的基本规则。A 用 ?acquire 拿到锁,B 在 A 持有时拿不到(返回 false),GET 看到 Session 是 A,LockIndex 为 1;B 不是持有者调 release 也是 false;A release 之后 Session 清空,LockIndex 仍是 1;B 立刻拿到锁,B 释放后 C 拿到,LockIndex 变成 3。用 LockIndex 当围栏令牌的演示(资源自己记住见过的最大令牌,是我写的几行,不是 Consul 的功能):A 令牌 1 写入通过,B 令牌 2 通过,已被换掉的 A 再用令牌 1 写入被拒。session 被销毁后:Behavior=delete 的锁 key 被删除(GET 返回 404);Behavior=release 的 key 还在,Session 清空,LockIndex 1,值 x。", t=tl(S(3)), mark=lidx(S(3), 'B acquire(A 持有时)', 'LockIndex 当围栏令牌'), done=lidx(S(3), 'A acquire', 'A release', 'C acquire', 'Behavior'), b=bars([['A 拿到后 LockIndex', 1, '1'], ['B 拿到后 LockIndex', 2, '2'], ['C 拿到后 LockIndex', 3, '3']], 3, done=[0, 1, 2]), kv=KV([['acquire', '持有时别人 false'], ['LockIndex', '每被拿到一次 +1(1 → 3)'], ['Behavior=delete', 'key 被删(404)'], ['Behavior=release', 'key 还在,Session 清空']], ['LockIndex'])),
    step("session 的 TTL。TTL 10 s(最小值)且不续约的 session:20.0 s 后才消失,锁随之释放,也就是 TTL 的两倍;每 3 s 续约一次的:45 s 内一直在,锁仍被持有;没有 TTL(只和节点的 serfHealth 挂钩)且持有者死了(不续约也不释放):45 s 内一直在,锁一直被占着。", t=tl(S(4)), mark=lidx(S(4), '(c)'), done=lidx(S(4), '(a)', '(b)'), b=bars([['TTL 10 s 不续约:消失 s', 20.0, '20.0'], ['TTL 10 s 每 3 s 续约', 45, '45 s 内一直在'], ['无 TTL、持有者死了', 45, '45 s 内一直在']], 45, done=[0], cur=[1], mark=[2]), kv=KV([['不续约', 'TTL 10 s → 20.0 s 才失效'], ['续约', '一直有效'], ['没有 TTL', '持有者死了锁也不会放']], ['没有 TTL'])),
    step("lock-delay。持有者的 session 被销毁后,B 每 0.1 s 尝试 acquire。持有者 session 的 lock-delay 为 0s:B 0.01 s 就拿到;3s:3.03 s 拿到;创建时不写(默认):15.04 s 才拿到。持有者自己 release 则不受这个延迟约束(第 3 步里 B 在 A 释放后立刻拿到了锁)。", t=tl(S(5)), mark=lidx(S(5), '不写(默认)'), done=lidx(S(5), '0s ', '3s '), b=bars([['lock-delay 0s', 0.01, '0.01 s'], ['lock-delay 3s', 3.03, '3.03 s'], ['不写(默认)', 15.04, '15.04 s']], 15.5, done=[0, 1], mark=[2]), kv=KV([['0s', '0.01 s 后可拿'], ['3s', '3.03 s 后可拿'], ['默认', '15.04 s 后可拿'], ['自己 release', '不受 lock-delay 影响']], ['默认'])),
    step("持有者所在节点故障时的切换。A 的 session 建在 client agent 上(TTL 10s),持有 leader 锁;SIGKILL 那个 agent。lock-delay 不写(默认):5.4 s 后 A 的锁被释放(等 gossip 判节点 failed,第 52 篇量过),20.3 s 后 B 才拿到锁(5.4 + 约 15 s 的 lock-delay);lock-delay 1s:5.9 s 释放,6.9 s 拿到。总时间是“发现节点没了”加“lock-delay”两段相加。", t=tl(S(6)), mark=lidx(S(6), '不写(默认)'), done=lidx(S(6), '1s '), b=bars([['默认:锁释放 s', 5.4, '5.4'], ['默认:B 拿到 s', 20.3, '20.3'], ['1s:锁释放 s', 5.9, '5.9'], ['1s:B 拿到 s', 6.9, '6.9']], 21, mark=[0, 1], done=[2, 3]), kv=KV([['默认 lock-delay', '杀掉后 20.3 s B 才拿到锁'], ['lock-delay 1s', '6.9 s'], ['先后顺序', '先 gossip 判 failed,再 lock-delay']], ['默认 lock-delay'])),
]
